-- 全部活跃含无时长记录者；时长仅为ta_mg_hide已上报的完成会话，未上报会话不估算。
SELECT day "数据日期",count(DISTINCT pid) "活跃人数",count(DISTINCT CASE WHEN duration_records>0 THEN pid END) "有时长记录人数",sum(duration_records) "时长记录数",round(sum(minutes),2) "在线总分钟",round(sum(minutes)/nullif(count(DISTINCT pid),0),2) "活跃人均在线分钟",count(DISTINCT CASE WHEN reg_day=date(day) THEN pid END) "新增人数",round(sum(CASE WHEN reg_day=date(day) THEN minutes ELSE 0 END)/nullif(count(DISTINCT CASE WHEN reg_day=date(day) THEN pid END),0),2) "新增首日人均在线分钟",cast(round(1.000000*count(DISTINCT CASE WHEN duration_records>0 THEN pid END)/nullif(count(DISTINCT pid),0),4) AS decimal(18,4)) "时长上报覆盖率" FROM (SELECT e."$part_date" day, u.pid, u.reg_day, u.channel_id, count_if(e."$part_event"='ad_log') ads, count_if(e."$part_event"='ad_log' AND e.result='1') ads_ok, sum(CASE WHEN e."$part_event"='ta_mg_hide' THEN coalesce(e."#duration",0) ELSE 0 END)/60.0 minutes, count_if(e."$part_event"='ta_mg_hide' AND e."#duration" IS NOT NULL) duration_records, count_if(e."$part_event"='battle_start') starts FROM ta.v_event_54 e JOIN (SELECT "#user_id",pid,reg_day,channel_id FROM (SELECT r.*,cast(reg_day AS varchar) "$part_date" FROM (SELECT "#user_id", coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) pid, date(min(first_login_time) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)))) reg_day, coalesce(first_value(channel_id) OVER(PARTITION BY coalesce(nullif(nb_open_id,''),nullif("#account_id",''),cast("#user_id" AS varchar)) ORDER BY first_login_time NULLS LAST),'未知') channel_id FROM ta.v_user_54 WHERE domain='release' AND game_name='yishuajiushangtou') r) registered WHERE ${PartDate:date2} AND ${Selector:selector3}) u ON e."#user_id"=u."#user_id" WHERE e.game_name='yishuajiushangtou' AND ${PartDate:date1} GROUP BY 1,2,3,4) a WHERE ${Selector:selector4} GROUP BY GROUPING SETS ((day),(day,channel_id)) HAVING GROUPING(channel_id)=1 ORDER BY 1 DESC,2